    status = response.status_code
    if status == 200:
        return response.json()
    elif status == 429:
        time.sleep(5)
        response = requests.get(url, headers=headers)
        if response.status_code == 200:
            return response.json()
        raise WeatherAPIError(f'Rate limit exceeded after retry: {response.status_code}')
    else:
        raise WeatherAPIError(f'Weather API error: {status}')

