import requests
import time

class NetworkFailureError(Exception):
    pass

class ClientFailureError(Exception):
    pass

class safe_request:
    def __init__(self, url, method='GET', max_retries=2):
        self.url = url
        self.method = method
        self.max_retries = max_retries
        self.response = None

    def __enter__(self):
        retries = 0
        while retries <= self.max_retries:
            self.response = requests.request(self.method, self.url)
            if 500 <= self.response.status_code < 600 and retries < self.max_retries:
                time.sleep(2)
                retries += 1
                continue
            break
        if self.response.status_code >= 500:
            raise NetworkFailureError(f'Network failure after {retries + 1} attempts')
        if 400 <= self.response.status_code < 500:
            raise ClientFailureError(f'Client error: {self.response.status_code}')
        return self.response

    def __exit__(self, exc_type, exc_val, exc_tb):
        if self.response is not None:
            self.response.close()
